```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) n, min(value) mn, max(value) mx, avg(value) av FROM abnormal_metrics WHERE attr_k8s_pod_name = 'rate-66f986cc46-sd6x7' AND metric IN ('k8s.container.ready','k8s.container.restarts','k8s.pod.phase') GROUP BY metric ORDER BY metric",
          "claim": "Rate pod stays not-ready (ready=0) while restarts climb from 2 to 6 through the abnormal window; normal restarts were 0."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, count(*) n, min(value) mn, max(value) mx, avg(value) av FROM abnormal_metrics WHERE metric = 'k8s.deployment.available' AND service_name = 'rate' GROUP BY 1,2",
          "claim": "The rate deployment reports 0 available replicas across every abnormal sample; it was 1.0 in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name = 'rate' GROUP BY 1",
          "claim": "rate emits no spans at all during the abnormal window (it had 529 server spans in the normal window)."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2",
          "claim": "Search's calls to rate.Rate/GetRates fail with Error status in about 0.014 ms, consistent with no reachable backend."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2",
          "claim": "Search's rate.Rate/GetRates client calls error out almost every time (1006 errors) once rate is unavailable."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2",
          "claim": "Frontend's /hotels requests return HTTP 500 (741 of 741) because the search.Search/Nearby call it depends on fails."
        }
      ]
    }
  ]
}
